(function(root){
const names={money:'Money kept',time:'Time kept',energy:'Effort saved',now:'Feelings now',later:'Feelings later',connection:'Connection',meaning:'Meaning',security:'Security'};
function decisionScore(options){const parts=[];let sum=0;for(const [key,label] of Object.entries(names)){const f=options.factors[key]||{weight:0};if(!Number.isFinite(f.weight)||f.weight<0||f.weight>5)throw Error(label+': choose importance from 0 to 5.');if(!f.weight)continue;if(!Number.isFinite(f.a)||!Number.isFinite(f.b))throw Error(label+': rate both options, or set importance to 0.');const resource=['money','time','energy'].includes(key);const swing=resource?f.swing:10;if(!Number.isFinite(swing)||swing<=0)throw Error(label+': enter a positive major-change amount.');const raw=(resource?f.b-f.a:f.a-f.b)/swing;parts.push({key,label,weight:f.weight,delta:Math.max(-1,Math.min(1,raw)),capped:Math.abs(raw)>1});sum+=f.weight;}
if(!sum)throw Error('Set at least one importance above 0 to calculate a combined score.');parts.forEach(f=>f.points=50*f.weight*f.delta/sum);const score=50+parts.reduce((v,f)=>v+f.points,0),low=50+parts.reduce((v,f)=>v+50*f.weight*Math.max(-1,f.delta-.1)/sum,0),high=50+parts.reduce((v,f)=>v+50*f.weight*Math.min(1,f.delta+.1)/sum,0);const violations=[];for(const [key,label] of [['money','spending'],['time','time'],['energy','effort']]){const limit=options.limits?.[key];if(limit!==null&&limit!==undefined){if(!Number.isFinite(limit)||limit<0)throw Error('Enter valid nonnegative hard limits.');if(options.factors[key].a>limit)violations.push(label);}}
return {score,parts,low,high,violations,boundary:!!options.declined,verdict:options.declined?'Respect their answer — step back':violations.length?'Main option exceeds your hard limit':score>55?'The main option looks worth it for your priorities':score<45?'The alternative looks better for your priorities':'Close call — neither option clearly wins'};}
if(typeof module==='object'&&module.exports)module.exports={decisionScore};if(!root.document)return;
const get=id=>document.getElementById(id),read=id=>get(id).value.trim()===''?NaN:Number(get(id).value),sign=n=>(n>0?'+':'')+n.toFixed(1);
function secondaryDetails(box,panel){if(Array.from(box.children).some(n=>n.dataset.secondary==='true'))return;const details=document.createElement('details');details.dataset.secondary='true';const summary=document.createElement('summary');summary.textContent='See individual forecasts and the full input table';details.append(summary);for(const node of Array.from(box.childNodes))if(node!==panel)details.append(node);box.append(details);}
function show(){if(!current)return;const old=get('decisionScoreResult');if(old)old.remove();const panel=document.createElement('section');panel.id='decisionScoreResult';panel.className='personal-result';get('numberDashboard').prepend(panel);const line=(tag,text)=>{const p=document.createElement(tag);p.textContent=text;panel.append(p)};const pairs={money:[read('money'),read('altMoney')],time:[read('minutes')+read('recovery'),read('altMinutes')+read('altRecovery')],energy:[read('energy'),read('altEffort')],now:[read('scoreDoNow'),read('scoreAltNow')],later:[read('scoreDoLater'),read('scoreAltLater')],connection:[read('fitDo_connection'),read('fitAlt_connection')],meaning:[read('fitDo_meaning'),read('fitAlt_meaning')],security:[read('fitDo_security'),read('fitAlt_security')]};
// Existing optional monetary and recovery inputs mean zero when left blank, consistent with their cost table.
for(const [key,ids] of [['money',['money','altMoney']],['time',['minutes','recovery','altMinutes','altRecovery']]]){const val=id=>get(id).value===''?0:read(id);pairs[key]=key==='money'?ids.map(val):[val(ids[0])+val(ids[1]),val(ids[2])+val(ids[3])];}
const input={factors:{},limits:{},declined:get('decisionType').value==='relationship'&&get('interest').value==='declined'};for(const key of Object.keys(names)){input.factors[key]={weight:read('decisionWeight_'+key),a:pairs[key][0],b:pairs[key][1],swing:['money','time','energy'].includes(key)?read('decisionSwing_'+key):10};}for(const [key,id] of [['money','decisionMaxMoney'],['time','decisionMaxTime'],['energy','decisionMaxEffort']])input.limits[key]=get(id).value===''?null:read(id);
try{const r=decisionScore(input);line('h3',`${r.score.toFixed(1)}/100 · ${r.verdict}`);line('p',`Main option: ${get('task').value}. Alternative: ${get('alt').value}. Higher scores favor the main option. This is a preference score, not a happiness forecast or probability.`);if(r.boundary)line('p','Their refusal or request for space overrides every score. Do not pursue this option.');if(r.violations.length)line('p','Hard limit override: the main option exceeds your '+r.violations.join(', ')+' limit.');for(const f of r.parts)line('p',`${f.label}: ${sign(f.points)} score points · importance ${f.weight}/5${f.capped?' · major-change cap reached':''}.`);line('p',`Assumption check: ${r.low.toFixed(1)}–${r.high.toFixed(1)}/100 if all included comparisons shift by ±0.1 normalized units. This is a sensitivity scenario, not a confidence interval.`);line('p','Calculation: 50 + 50 × weighted mean of capped factor changes. Resource change = (alternative cost − main cost) / your major-change amount. Benefit change = (main rating − alternative rating) / 10. Each factor is capped at −1 to +1.');current.decisionTradeoff={inputs:input,result:r};current.profileSummary+='\n\nCOMBINED PERSONAL DECISION SCORE\n'+panel.textContent;}catch(e){line('h3','Personalized score needs your input');line('p',e.message);delete current.decisionTradeoff;}secondaryDetails(get('numberDashboard'),panel);}
get('form').addEventListener('submit',show);
const before=renderNumbers;renderNumbers=function(){before();show()};
for(const id of ['example','purchaseExample','relationshipExample'])get(id).addEventListener('click',()=>{for(const key of Object.keys(names))get('decisionWeight_'+key).value=0;for(const [key,w,swing] of [['money',2,50],['time',3,60],['energy',3,2],['now',3],['later',4]]){get('decisionWeight_'+key).value=w;if(swing)get('decisionSwing_'+key).value=swing;}get('decisionMaxMoney').value='';get('decisionMaxTime').value='';get('decisionMaxEffort').value='';show()});
get('decisionScoreSettings').addEventListener('input',()=>{if(current&&get('form').checkValidity()){addPerspective();renderNumbers()}});
})(typeof globalThis!=='undefined'?globalThis:this);
